INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (21, '艾伦·图灵', 'Alan Turing', '1912—1954', '20世纪', '英国', '数学家', ARRAY['科学家', '英国', '计算机'], '英国数学家与逻辑学家，计算机科学与人工智能的奠基者。二战中他破译德军密码，战后提出图灵机与图灵测试。', '同事', '', 'assets/figures/turing.jpg', ARRAY['06-23', '12-12'], ARRAY['诞辰 · 1912年6月23日', '论文发表 · 1936年12月12日'], ARRAY['birth', 'event'], '他上班时总是安静地走路，同事们很久以后才明白他在算什么。', ARRAY['同事', '破译组炊事'], ARRAY['他上班时总是安静地走路，同事们很久以后才明白他在算什么。', '布莱切利园里半夜加班的只有他和你，你负责把茶端进密室。']),
  (22, '阿达·洛芙莱斯', 'Ada Lovelace', '1815—1852', '19世纪', '英国', '数学家', ARRAY['科学家', '英国', '计算机'], '英国数学家，被公认为史上第一位程序员。她为巴贝奇的分析机写下算法，预见了计算机超越纯计算的潜力。', '合伙投资人', '', 'assets/figures/ada.jpg', ARRAY['12-10', '08-01'], ARRAY['诞辰 · 1815年12月10日', '注释出版 · 1843年8月1日'], ARRAY['birth', 'event'], '巴贝奇的机器要有人替它写第一批程序——那个人就是你。', ARRAY['合伙投资人', '差分机描图员'], ARRAY['巴贝奇的机器要有人替它写第一批程序——那个人就是你。', '分析机的图纸浩如烟海，描图描到手腕酸的那个人是你。']),
  (23, '罗莎琳德·富兰克林', 'Rosalind Franklin', '1920—1958', '20世纪', '英国', '化学家', ARRAY['科学家', '英国', '生物'], '英国物理化学家，以X射线衍射揭示DNA结构的关键证据。她的51号照片为双螺旋模型提供了决定性支撑。', '同实验室的人', '', 'assets/figures/franklin.jpg', ARRAY['07-25', '05-02'], ARRAY['诞辰 · 1920年7月25日', '51号照片 · 1952年5月2日'], ARRAY['birth', 'event'], '那张著名的照片署了别人的名字，而拍照的人是你。', ARRAY['同实验室的人', '暗房助手'], ARRAY['那张著名的照片署了别人的名字，而拍照的人是你。', '暗房里显影定影总得有人守，半夜里陪她的是你。']),
  (24, '列奥纳多·达·芬奇', 'Leonardo da Vinci', '1452—1519', '文艺复兴', '意大利', '画家 · 博学家', ARRAY['画家', '意大利', '文艺复兴'], '意大利文艺复兴的通才，画家、工程师、解剖学家于一身。《蒙娜丽莎》与《最后的晚餐》是他不朽的杰作。', '合租室友', '', 'assets/figures/leonardo.jpg', ARRAY['04-15', '05-02'], ARRAY['诞辰 · 1452年4月15日', '《蒙娜丽莎》完成 · 1519年5月2日'], ARRAY['birth', 'event'], '他住你对门，整夜不睡，画满了没人看懂的机器图纸。', ARRAY['合租室友', '宫廷琴师'], ARRAY['他住你对门，整夜不睡，画满了没人看懂的机器图纸。', '他还是个出色的 lyre 琴手，宫廷宴上和你合奏过不止一回。']),
  (25, '米开朗基罗', 'Michelangelo', '1475—1564', '文艺复兴', '意大利', '雕塑家 · 画家', ARRAY['画家', '意大利', '文艺复兴'], '意大利文艺复兴巨匠，雕塑、绘画、建筑兼擅。西斯廷天顶画与雕塑《大卫》定义了文艺复兴的艺术高度。', '房客', '', 'assets/figures/michelangelo.jpg', ARRAY['03-06', '10-31'], ARRAY['诞辰 · 1475年3月6日', '西斯廷揭幕 · 1512年10月31日'], ARRAY['birth', 'event'], '他脾气坏到房东都受不了，却从没赶走过一个付了房租的人。', ARRAY['房客', '采石场工友'], ARRAY['他脾气坏到房东都受不了，却从没赶走过一个付了房租的人。', '他挑大理石极挑剔，采石场里跟他一起抡锤的是你。']),
  (26, '卡拉瓦乔', 'Caravaggio', '1571—1610', '文艺复兴', '意大利', '画家', ARRAY['画家', '意大利', '巴洛克'], '意大利巴洛克绘画的开创者，以强烈的明暗对比和写实的人物著称。他一生好斗，画作却深刻影响了欧洲画坛。', '模特', '', 'assets/figures/caravaggio.jpg', ARRAY['10-29', '05-31'], ARRAY['诞辰 · 1571年10月29日', '《圣马太蒙难》 · 1599年5月31日'], ARRAY['birth', 'event'], '他画圣人的时候用的是酒馆里的小人物——你也给他做过模特。', ARRAY['模特', '决斗陪练'], ARRAY['他画圣人的时候用的是酒馆里的小人物——你也给他做过模特。', '他动辄拔剑，街头上替他挡过刀、又陪他练过剑的是你。']),
  (27, '伦勃朗', 'Rembrandt', '1606—1669', '17世纪', '荷兰', '画家', ARRAY['画家', '荷兰', '黄金时代'], '荷兰黄金时代最伟大的画家之一。他以深邃的光影与人物心理刻画闻名，自画像系列贯穿一生。', '债主', '', 'assets/figures/rembrandt.jpg', ARRAY['07-15', '11-14'], ARRAY['诞辰 · 1606年7月15日', '阿姆斯特丹大审判 · 1665年11月14日'], ARRAY['birth', 'event'], '他破产之后，是你替他垫的债；然后他把你画进了画面里。', ARRAY['债主', '画室伙计'], ARRAY['他破产之后，是你替他垫的债；然后他把你画进了画面里。', '他画室里研墨、绷画布、管颜料的那个人，一直是你。']),
  (28, '文森特·梵高', 'Vincent van Gogh', '1853—1890', '19世纪', '荷兰', '画家', ARRAY['画家', '荷兰', '后印象派'], '荷兰后印象派画家，生前寂寂无名。他以炽烈的色彩与笔触表达内心，死后成为现代艺术最具号召力的名字。', '房客', '', 'assets/figures/vangogh.jpg', ARRAY['03-30', '12-23'], ARRAY['诞辰 · 1853年3月30日', '来到阿尔勒 · 1888年12月23日'], ARRAY['birth', 'event'], '他付不起房租的那几个月，是你替他挡的房东。', ARRAY['房客', '颜料店掌柜'], ARRAY['他付不起房租的那几个月，是你替他挡的房东。', '他总买最贵的铬黄，记账、赊账、退色的那本子攥在你手里。']),
  (29, '克劳德·莫奈', 'Claude Monet', '1840—1926', '19世纪', '法国', '画家', ARRAY['画家', '法国', '印象派'], '法国画家，印象派运动的命名者与核心人物。《日出·印象》催生了整个流派，他晚年沉迷于睡莲系列。', '邻居', '', 'assets/figures/monet.jpg', ARRAY['11-14', '08-05'], ARRAY['诞辰 · 1840年11月14日', '《日出·印象》展出 · 1874年8月5日'], ARRAY['birth', 'event'], '他在吉维尼的花园里种了一辈子睡莲，邻居都看惯了。', ARRAY['邻居', '水上画舫'], ARRAY['他在吉维尼的花园里种了一辈子睡莲，邻居都看惯了。', '他爱在船上写生，摇橹撑篙、替他稳住画板的那个船夫是你。']),
  (30, '巴勃罗·毕加索', 'Pablo Picasso', '1881—1973', '19—20世纪', '西班牙', '画家', ARRAY['画家', '西班牙', '立体派'], '西班牙画家与雕塑家，立体主义的共同创立者。他风格多变、产量惊人，是20世纪最具影响力的艺术家之一。', '牌搭子', '', 'assets/figures/picasso.jpg', ARRAY['10-25', '06-01'], ARRAY['诞辰 · 1881年10月25日', '《格尔尼卡》 · 1937年6月1日'], ARRAY['birth', 'event'], '他把画画当成一局很长的棋，输了就拿对方的画当赌注。', ARRAY['牌搭子', '陶窑伙计'], ARRAY['他把画画当成一局很长的棋，输了就拿对方的画当赌注。', '他迷上陶艺那年，陪他揉泥、转轮、守窑的那个人是你。'])
